from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# --------------------------------------------------------------------------- Tag


class TestTag:
    def test_valid_tag(self):
        t = Tag("Python")
        assert t.name == "python"

    def test_strips_whitespace(self):
        t = Tag("  Django  ")
        assert t.name == "django"

    def test_allows_hyphens_underscores_digits(self):
        t = Tag("my-tag_2")
        assert t.name == "my-tag_2"

    @pytest.mark.parametrize("bad", ["", "   ", None])
    def test_rejects_empty_or_none(self, bad):
        if bad is None:
            with pytest.raises(TypeError):
                Tag(bad)
        else:
            with pytest.raises(ValueError, match="must not be empty"):
                Tag(bad)

    def test_rejects_too_long(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    @pytest.mark.parametrize("ch", ["!", "@", " space", "a b"])
    def test_rejects_illegal_characters(self, ch):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(ch)


# ---------------------------------------------------------------- TaskPriority


class TestTaskPriority:
    def test_order_key_ranking(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(
            TaskPriority.MEDIUM
        )
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(
            TaskPriority.LOW
        )

    def test_str_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"


# ----------------------------------------------------------------- TaskStatus


