    NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)

    def test_overdue_when_due_in_past_and_pending(self):
        task = Task(
            id=1,
            title="x",
            due_at=self.NOW - timedelta(hours=1),
            created_at=self.NOW,
        )
        assert task.is_overdue(self.NOW) is True

    def test_not_overdue_when_no_due_date(self):
