from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(
    id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
    due_at=None, tags=None, created_at=None,
):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


# --------------------------------------------------------- TaskQuery validation


class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("bad_limit", [0, -1, 101, "abc"])
    def test_invalid_limit(self, bad_limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=bad_limit)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalization(self):
        q = TaskQuery(tag="  Python  ")
        assert q.tag == "python"

    def test_search_whitespace_stripped_to_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_preserved_when_valid(self):
        q = TaskQuery(search=" buy ")
        assert q.search == "buy"


# --------------------------------------------------------- TaskPage.has_more


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_task(1)], total=1, limit=20, offset=0)
        assert page.has_more is False


# ------------------------------------------------------------ filtering


class TestApplyQueryFiltering:
    TASKS = [
        _task(1, "Buy milk", status=TaskStatus.PENDING, tags=[Tag("errand")]),
        _task(2, "Write tests", status=TaskStatus.DONE, tags=[Tag("dev")]),
        _task(3, "Buy bread", status=TaskStatus.PENDING,
              due_at=NOW - timedelta(hours=1)),
    ]

    def test_filter_by_status_pending(self):
        page = apply_query(self.TASKS, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert len(page.items) == 2
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_by_status_done(self):
        page = apply_query(self.TASKS, TaskQuery(status=TaskStatus.DONE), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self):
        page = apply_query(self.TASKS, TaskQuery(tag="errand"), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 1

    def test_filter_by_search(self):
        page = apply_query(self.TASKS, TaskQuery(search="buy"), NOW)
        ids = {t.id for t in page.items}
        assert ids == {1, 3}

    def test_filter_overdue_true(self):
        page = apply_query(self.TASKS, TaskQuery(overdue=True), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self):
        page = apply_query(self.TASKS, TaskQuery(overdue=False), NOW)
        ids = {t.id for t in page.items}
        assert 3 not in ids

    def test_no_filters_returns_all(self):
        page = apply_query(self.TASKS, TaskQuery(), NOW)
        assert page.total == 3


# ------------------------------------------------------------- sorting


class TestApplyQuerySorting:
    def test_sort_by_title(self):
        tasks = [_task(1, "Zebra"), _task(2, "Apple")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.id for t in page.items] == [2, 1]

    def test_sort_by_priority(self):
        tasks = [
            _task(1, priority=TaskPriority.LOW),
            _task(2, priority=TaskPriority.HIGH),
            _task(3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]

    def test_sort_descending(self):
        tasks = [_task(1, "A"), _task(2, "B")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.id for t in page.items] == [2, 1]

    def test_sort_by_due_at_none_last(self):
        tasks = [
            _task(1, due_at=None),
            _task(2, due_at=NOW - timedelta(hours=2)),
            _task(3, due_at=NOW + timedelta(hours=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]

    def test_sort_by_created_at(self):
        tasks = [
            _task(1, created_at=NOW + timedelta(hours=1)),
            _task(2, created_at=NOW - timedelta(hours=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [2, 1]


# ---------------------------------------------------------- pagination


class TestApplyQueryPagination:
    TASKS = [_task(i, f"task-{i}") for i in range(1, 6)]

    def test_limit_and_offset(self):
        page = apply_query(self.TASKS, TaskQuery(limit=2, offset=1), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.offset == 1
        assert page.has_more is True

    def test_offset_past_end(self):
        page = apply_query(self.TASKS, TaskQuery(limit=10, offset=10), NOW)
        assert len(page.items) == 0
        assert page.has_more is False

    def test_last_page(self):
        page = apply_query(self.TASKS, TaskQuery(limit=3, offset=3), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags
from tests.conftest import FIXED_NOW, make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2))
        items = list(repo.list())
        assert len(items) == 2

    def test_update_existing(self, repo):
        repo.add(make_task(id=1, title="old"))
        updated = make_task(id=1, title="new")
        repo.update(updated)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=99))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("python"), Tag("Python")])
        assert len(result) == 1
        assert result[0].name == "python"

    def test_strings_converted(self):
        result = normalize_tags(["Flask", "django"])
        assert all(isinstance(t, Tag) for t in result)
        assert result[0].name == "flask"

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["b", "a", "b"])
        assert [t.name for t in result] == ["b", "a"]

    def test_empty_input(self):
        assert normalize_tags([]) == []
